import{_ as i,o as t,a as _,b as a}from"./app.DKoEZOcr.js";const l="/ascendc.github.io/pr/5487/assets/nz2nz_l0c2ub_dual_dst.DZpQKqpj.png",s="/ascendc.github.io/pr/5487/assets/nz2nd_l0c2ub_dual_dst.CyGvW9FJ.png",N=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/cube_store_key_features"},{"text":"L0C到UB双目标模式","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/L0C_to_UB_dual_target_mode"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/L0C_to_UB_dual_target_mode.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/L0C_to_UB_dual_target_mode.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"特性约束","slug":"特性约束","link":"#特性约束"},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"}],"lastUpdated":1787050286000}'),r={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/L0C_to_UB_dual_target_mode.md"};function p(c,e,u,o,d,n){return t(),_("div",null,[...e[0]||(e[0]=[a('<div><article class="markdown-body"><h1>L0C Buffer到UB双目标模式</h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>同一AI Core内有一个Cube Core和两个Vector Core，当启用双目标模式控制时，L0C Buffer中的M×N矩阵将被分成两半，并同时分别写入两个Vector Core各自的Unified Buffer（UB）中，其中前半部分写入SUB BLOCK0，后半部分写入SUB BLOCK1。</p><ul><li>双目标模式（M维度）：按M维度拆分成形状为M / 2 * N的两个矩阵，分别写入两个UB。</li><li>双目标模式（N维度）：按N维度拆分成形状为M * N / 2的两个矩阵，分别写入两个UB。</li></ul><h2 id="特性约束">特性约束<a class="header-anchor" href="#特性约束">​</a></h2><ul><li>双目标模式仅支持在L0C Buffer到UB通路，普通搬运模式（NZ2NZ）或NZ2ND搬运场景下使用，不支持随路功能场景。</li><li>按M维度拆分时M必须为2的倍数。</li><li>按N维度拆分时N须为32的倍数。</li></ul><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><p>在普通搬运模式模式下启用双目标模式如下图所示，分为按M维度拆分和按N维度拆分，按M维度拆分M必须为2的倍数，按N维度拆分N必须为32的倍数：</p><p>N方向切分：</p><ul><li>nSize = 32，表示源NZ矩阵中待搬运矩阵在N方向上的大小为32个元素。</li><li>mSize = 48，表示源NZ矩阵中待搬运矩阵在M方向上的大小48个元素。</li><li>srcStride = 64，表示源NZ矩阵中待搬运矩阵相邻Z排布的起始地址偏移，即下图中第一个块Z排布矩阵的起始地址与第二个Z排布矩阵的起始地址之间的间隔为64 * C0_Size。</li><li>dstStride = 64 * C0，表示目的NZ矩阵中相邻Z排布的起始地址偏移，即下图中UB0中Z排布的起始地址与UB1中Z排布的起始地址之间的间隔为64 * 16个元素。</li></ul><p>M方向切分：</p><ul><li>nSize = 32，表示源NZ矩阵中待搬运矩阵在N方向上的大小为32个元素。</li><li>mSize = 24，表示源NZ矩阵中待搬运矩阵在M方向上的大小为24个元素。</li><li>srcStride = 64，表示源NZ矩阵中待搬运矩阵相邻Z排布的起始地址偏移，即下图中第一个块Z排布矩阵的起始地址与第二个Z排布矩阵的起始地址之间的间隔为64 * C0_Size。</li><li>dstStride = 40 * C0，表示目的NZ矩阵中相邻Z排布的起始地址偏移，即下图中UB0（或UB1）中第一个Z排布的起始地址与第二个Z排布的起始地址之间的间隔为40 * 16个元素。</li></ul><p><strong>图1</strong> NZ2NZ双目标搬运模式设置示意图<span id="fig1386816164556"></span></p><p><img src="'+l+'" alt></p><p>在NZ2ND模式下启用双目标模式如下图所示，分为按M维度拆分和按N维度拆分，按M维度拆分M必须为2的倍数，按N维度拆分N必须为2的倍数：</p><ul><li>ndNum = 2，表示源NZ矩阵的数目为2。图中红框区域为矩阵1，蓝框区域为矩阵2。</li><li>nSize = 32，表示源NZ矩阵（图中红框区域或蓝框区域）在N方向上的大小为32个元素。</li><li>mSize = 48，表示源NZ矩阵在M方向上的大小为48个元素。</li><li>srcStride = 64，表示源NZ矩阵中相邻Z排布的起始地址偏移，即下图红框区域中左侧浅色Z排布矩阵的起始地址与右侧深色Z排布矩阵的起始地址之间的间隔为64 * C0_Size。</li><li>dstStride = 64，表示目的ND矩阵每一行中的元素个数为64。</li><li>ndNum = 2, 表示源NZ矩阵的数目。</li><li>srcNdStride = 240 , 表示不同NZ矩阵起始地址之间的间隔为240 * C0_Size。</li><li>dstNdStride = 4096，表示目的相邻ND矩阵起始地址之间的偏移为4096个元素。</li></ul><p><strong>图2</strong> NZ2ND参数双搬入模式设置示意图<span id="fig715654093716"></span></p><p><img src="'+s+'" alt></p><p>完整样例可参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/03_matrix_compute/fixpipe_l0c2ub">fixpipe_l0c2ub</a>。</p></article></div>',1)])])}const I=i(r,[["render",p]]);export{N as __pageData,I as default};
